// ── SignalR Manager ──────────────────────────────────────────────
// Output 1: access event (object) → http request
// Output 2: error (string) → debug

const AC_BASE = env.get('AC_BASE_URL');
const AC_TOKEN = env.get('AC_API_TOKEN');
const BACKEND = env.get('BACKEND_URL');
const NR_SECRET = env.get('NODE_RED_SECRET');

const state = global.get('signalr_state') || 'disconnected';
if (state === 'connected' || state === 'connecting') {
    node.log('SignalR ya ' + state + ', skip');
    return null;
}

global.set('signalr_state', 'connecting');
node.log('Iniciando conexión SignalR a ' + AC_BASE);

const https = require('https');
const negUrl = new URL(AC_BASE + '/mainhubv3/negotiate?negotiateVersion=1');

const negOpts = {
    hostname: negUrl.hostname,
    port: negUrl.port || 443,
    path: negUrl.pathname + negUrl.search,
    method: 'POST',
    headers: { 'Authorization': 'Bearer ' + AC_TOKEN, 'Content-Length': 0 },
    rejectUnauthorized: false
};

const negReq = https.request(negOpts, (res) => {
    let body = '';
    res.on('data', c => body += c);
    res.on('end', () => {
        if (res.statusCode !== 200) {
            node.send([null, { payload: 'Negotiate ' + res.statusCode + ': ' + body.slice(0, 200) }]);
            global.set('signalr_state', 'disconnected');
            return;
        }
        let neg;
        try { neg = JSON.parse(body); }
        catch(e) {
            node.send([null, { payload: 'Negotiate JSON inválido: ' + body.slice(0, 100) }]);
            global.set('signalr_state', 'disconnected');
            return;
        }
        const token = neg.connectionToken || neg.connectionId;
        if (!token) {
            node.send([null, { payload: 'Negotiate: sin connectionToken. ' + body.slice(0, 200) }]);
            global.set('signalr_state', 'disconnected');
            return;
        }
        const wsBase = AC_BASE.replace(/^https:\/\//, 'wss://').replace(/^http:\/\//, 'ws://');
        const wsUrl = wsBase + '/mainhubv3?id=' + encodeURIComponent(token) + '&negotiateVersion=1';
        node.log('Abriendo WebSocket: ' + wsUrl.split('?')[0]);
        let ws;
        try {
            const WS = require('ws');
            ws = new WS(wsUrl, { headers: { Authorization: 'Bearer ' + AC_TOKEN }, rejectUnauthorized: false });
        } catch(e) {
            node.send([null, { payload: 'No se pudo abrir WebSocket: ' + e.message }]);
            global.set('signalr_state', 'disconnected');
            return;
        }
        global.set('signalr_ws', ws);
        let handshakeDone = false;
        ws.on('open', () => {
            node.log('WS conectado — enviando handshake SignalR');
            ws.send(JSON.stringify({ protocol: 'json', version: 1 }) + '\u001e');
        });
        ws.on('message', (data) => {
            const str = Buffer.isBuffer(data) ? data.toString('utf8') : String(data);
            const frames = str.split('\u001e').filter(f => f.trim() && f.trim() !== '{}');
            for (const frame of frames) {
                let msg;
                try { msg = JSON.parse(frame); } catch(e) { continue; }
                if (!handshakeDone) {
                    handshakeDone = true;
                    global.set('signalr_state', 'connected');
                    node.log('Handshake OK — suscribiendo a accesslog');
                    ws.send(JSON.stringify({ type: 1, target: 'Subscribe', arguments: ['accesslog', null], invocationId: '0' }) + '\u001e');
                    continue;
                }
                if (msg.type === 6) {
                    ws.send(JSON.stringify({ type: 6 }) + '\u001e');
                    continue;
                }
                if (msg.type === 1 && msg.target === 'ReceiveMessage') {
                    const payload = Array.isArray(msg.arguments) ? msg.arguments[0] : null;
                    if (payload) {
                        const eventData = payload.data || payload;
                        node.log('Evento: ' + JSON.stringify(eventData).slice(0, 150));
                        node.send([{
                            payload: JSON.stringify(eventData),
                            headers: {
                                'Content-Type': 'application/json',
                                'X-Node-Red-Secret': NR_SECRET
                            },
                            url: BACKEND + '/webhooks/node-red/access-event'
                        }, null]);
                    }
                }
            }
        });
        ws.on('error', (err) => {
            node.send([null, { payload: 'WS error: ' + err.message }]);
            global.set('signalr_state', 'disconnected');
        });
        ws.on('close', (code, reason) => {
            const r = reason ? reason.toString() : '';
            node.warn('WS cerrado: ' + code + ' ' + r);
            global.set('signalr_state', 'disconnected');
        });
    });
});
negReq.on('error', (err) => {
    node.send([null, { payload: 'Error negotiate: ' + err.message }]);
    global.set('signalr_state', 'disconnected');
});
negReq.end();
return null;

finalize:
const ws = global.get('signalr_ws');
if (ws) { try { ws.close(); } catch(e) {} global.set('signalr_ws', null); }
global.set('signalr_state', 'disconnected');
node.log('SignalR cerrado (redeploy)');
